from collections.abc import Callable, Mapping
from typing import Any, TypedDict
from langgraph.graph import END, START, StateGraph

class ControlState(TypedDict):
    run_id: str
    next: str                    # 由可信节点依据事实计算，不直接采用模型文本
    frozen_spec_id: str | None

Node = Callable[[ControlState], dict[str, Any]]

def build_graph(impl: Mapping[str, Node], checkpointer: Any):
    """依赖注入示意：节点和持久 checkpointer 由服务装配。"""
    names = ("hydrate", "specify", "freeze", "plan",
             "compile_enqueue", "collect_validate", "report")
    builder = StateGraph(ControlState)

    def enqueue(state: ControlState) -> dict[str, Any]:
        if state["frozen_spec_id"] is None:
            raise ValueError("SPEC_NOT_FROZEN")
        # impl 内还须校验冻结记录、已编译 Plan、scope 和剩余预算；
        # 事务提交 Attempt / operation_id / 预算预留 / outbox，不在此计算。
        return impl["compile_enqueue"](state)

    for name in names:
        node = enqueue if name == "compile_enqueue" else impl[name]
        builder.add_node(name, node)
    routes = {name: name for name in names}
    routes.update({"WAITING_INPUT": END, "WAITING_TOOL": END,
                   "DONE": END, "STOP": END})
    builder.add_edge(START, "hydrate")
    for name in names:
        builder.add_conditional_edges(name, lambda s: s["next"], routes)
    return builder.compile(checkpointer=checkpointer)
